const PLATFORM_SLUG: Record<string, string> = {
	"wordpress": "wordpress",
	"shopify": "shopify",
	"wix": "wix",
	"squarespace": "squarespace",
	"webflow": "webflow",
	"ghost": "ghost",
	"drupal": "drupal",
	"joomla": "joomla",
	"prestashop": "prestashop",
	"nextjs": "nextdotjs",
	"nuxt": "nuxt",
	"gatsby": "gatsby",
	"hugo": "hugo",
	"jekyll": "jekyll",
};

/** The product mark of a collector kind, if it has one. */
export function kindBrand(kind: string): BrandIcon | null {
	const slug = KIND_SLUG[kind];
	return slug ? (ICONS[slug] ?? null) : null;
}

/** The mark of a website platform detected by the `website` kind, if it has one. */
export function platformBrand(platform: string | null | undefined): BrandIcon | null {
	const slug = platform ? PLATFORM_SLUG[platform] : undefined;
	return slug ? (ICONS[slug] ?? null) : null;
}
